INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'a3284661-696c-5ddb-bed7-92ecce6ddaea', 'f9e44ac9-1c7c-55ab-a0c6-a1c28c508f9e',
  '1. Dùng mảng A[0...5] để hiện thực hàng đợi vòng (circular queue), giả sử rear = 0 và front = 3. Giá trị của rear và front sau khi xóa 1 phần tử và thêm 2 phần tử mới vào hàng đợi.

