INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '8196b830-d522-51db-8b33-8a76245624a5', 'f9e44ac9-1c7c-55ab-a0c6-a1c28c508f9e',
  '2. Một danh sách lưu trữ các phần tử có kích thước lớn. Nhu cầu thêm, xóa, và truy xuất trên danh sách này là ngang nhau. Giải pháp nào tốt nhất cho trường hợp này
    (a) Danh sách liên tục
    (b) Danh sách liên kết
    (c) Danh sách dùng Hash
    (d) Danh sách liên tục sử dụng cấu trúc liên kết

Lựa chọn:
- (a) Danh sách liên tục
- (b) Danh sách liên kết
- (c) Danh sách dùng Hash
- (d) Danh sách liên tục sử dụng cấu trúc liên kết', 2
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '436b1197-f8aa-5a07-9c95-1d5d159a2e57', 'f9e44ac9-1c7c-55ab-a0c6-a1c28c508f9e',
  '3. Cho một stack thực thi kích thước $N$. Một hàm đệ quy $f(i) = f(i/2) + f(i-2); f(i|i < 2) = 1$ sẽ sử dụng stack này, mỗi lời gọi đệ quy sẽ đặt một block dữ liệu kích thước $M$ trên stack. Hãy xác định giới hạn của input khi gọi $f(i)$ [2.1, 16]

Lựa chọn:
- (a) $N/M < \log_2(i)$
- (b) $i < 2N/M$
- (c) $i < N/M + 1$
- (d) $i < N/M$', 3
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
