INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '017f32de-3b00-524b-82ef-b58bc3ab6c3b', 'f9e44ac9-1c7c-55ab-a0c6-a1c28c508f9e',
  '5. Phương pháp sắp xếp nào mà ở mỗi bước, giải thuật sẽ lựa chọn giá trị nhỏ nhất trong phần chưa được sắp xếp, sau đó chen vào cuối phần đã được sắp xếp:
