);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'c27f2d88-15ee-58f3-a1b7-3d1395bb64c5', 'f9e44ac9-1c7c-55ab-a0c6-a1c28c508f9e',
  '6. Sử dụng phương pháp Quick Sort để sắp xếp dãy số (28, 16, 32, 12, 60, 2, 5, 72) theo thứ tự từ nhỏ đến lớn. Hãy cho biết kết quả sau khi tiến hành thao tác Partition lần đầu tiên (lấy phần tử đầu tiên làm pivot, hoán pivot với phần tử cuối trong partition đầu).

