);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '448b0cf4-43b5-50fb-b643-c34771c12606', 'f9e44ac9-1c7c-55ab-a0c6-a1c28c508f9e',
  '8. Sắp xếp dãy số sau {15, 9, 7, 8, 20, -1, 4}, giả sử sau một bước chạy, ta nhận được kết quả là {4, 9, -1, 8, 20, 7, 15}. Hãy cho biết phương pháp sắp xếp được sử dụng là:
