INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'fe324711-d087-5bc8-9391-5eeb736d71d2', 'f9e44ac9-1c7c-55ab-a0c6-a1c28c508f9e',
  '12. Chọn phát biểu đúng nhất.
(a) Giải thuật tìm đường Dijkstra cho kết quả đường đi ngắn nhất.
(b) Giải thuật Prim cho kết quả đường đi tối ưu.
