INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  '5610955e-622b-55a8-86bb-a23e988c491b', 'f9e44ac9-1c7c-55ab-a0c6-a1c28c508f9e',
  '27. (1.0 điểm) Bảo hiểm tự nguyện hỗ trợ khách hàng khắc phục hậu quả thiệt hại về xe trong trường hợp chủ xe tự gây ra các tổn thất không mong muốn mà không có tác động của bên thứ ba. Khi xảy ra các sự cố liên quan đến xe, để có thể được nhận bởi thưởng từ bảo hiểm, người sử dụng dịch vụ bảo hiểm cần liên hệ với đơn vị bảo hiểm để thông báo tai nạn, thông tin thông báo gồm:

*   Tên, điện thoại của người thông báo
*   Biển số xe
*   Ngày giờ, địa điểm, diễn biến tai nạn

Đây là quy định bắt buộc lái xe phải tuần theo để đảm bảo được hưởng toàn bộ quyền lợi nếu không muốn bị phạt chế tài trong quá trình thực hiện bảo hiểm ( mức chế tài từ 10 đến 50% tổng chi phí sửa chữa) trong một số trường hợp đơn vị bảo hiểm còn từ chối bồi thường nếu vi phạm quy định này.

(a) Hãy dùng mã giả (pseudocode) (hoặc mã C++) để đặc tả cấu trúc dữ liệu phù hợp để đặc tả thông tin trên.

............................................................................................................................
............................................................................................................................
............................................................................................................................
............................................................................................................................
............................................................................................................................
............................................................................................................................

(b) Hãy đặc tả các method cơ bản cho cấu trúc trên. [3.3] (0.4)

............................................................................................................................
............................................................................................................................', 25
);

INSERT INTO question_bank_2_examples (id, group_id, content, sequence)
VALUES (
  'fed289ee-d21b-5424-bca5-4e2bab0012a7', 'f9e44ac9-1c7c-55ab-a0c6-a1c28c508f9e',
  '28. **(1đ)** Một hệ thống máy chủ tiếp nhận các record thông báo tai nạn như nội dung tại câu 27 gửi về.

(a) Hệ thống máy chủ sử dụng một hàng đợi vòng để tiếp nhận và xử lý các thông báo đến từ ứng dụng người dùng. Hàng đợi (vòng) này có thể được khởi động với kích thước tùy biến. Hãy đặc tả cấu trữ dữ liệu tiếp nhận và xử lý tại server.

(b) Hiện thực phương thức `int enqueue(dRecord* pData)` (trả về số slot còn trống trong hàng đợi). [2.4] (1.0)', 26
);

